CREATE TABLE dispatch.rescue_plan (id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES org.company(id),order_id uuid NOT NULL,exception_id uuid NOT NULL,version bigint NOT NULL DEFAULT 1,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES org.principal(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(company_id,id),UNIQUE(company_id,exception_id),FOREIGN KEY(company_id,order_id) REFERENCES orders.draft(company_id,id),FOREIGN KEY(company_id,exception_id) REFERENCES casework.dispatch_exception(company_id,id));
CREATE TABLE dispatch.rescue_assignment (id uuid PRIMARY KEY,company_id uuid NOT NULL,plan_id uuid NOT NULL,vehicle_id uuid NOT NULL,driver_id uuid NOT NULL,route_plan_version_id uuid NOT NULL,load_review_id uuid NOT NULL,snapshot jsonb NOT NULL,UNIQUE(company_id,id),FOREIGN KEY(company_id,plan_id) REFERENCES dispatch.rescue_plan(company_id,id),FOREIGN KEY(company_id,vehicle_id) REFERENCES fleet.vehicle(company_id,id),FOREIGN KEY(company_id,driver_id) REFERENCES org.principal(company_id,id),FOREIGN KEY(company_id,route_plan_version_id) REFERENCES dispatch.route_plan_version(company_id,id),FOREIGN KEY(company_id,load_review_id) REFERENCES dispatch.load_review(company_id,id));
CREATE TABLE dispatch.rescue_assignment_package (company_id uuid NOT NULL,assignment_id uuid NOT NULL,package_id uuid NOT NULL,PRIMARY KEY(company_id,assignment_id,package_id),UNIQUE(company_id,package_id),FOREIGN KEY(company_id,assignment_id) REFERENCES dispatch.rescue_assignment(company_id,id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['dispatch.rescue_plan','dispatch.rescue_assignment','dispatch.rescue_assignment_package'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format($p$CREATE POLICY company_scope ON %s USING(company_id=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=NULLIF(current_setting('app.company_id',true),'')::uuid)$p$,t);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION pricing.reject_history_change()',t);EXECUTE format('GRANT SELECT,INSERT ON %s TO routefit_api',t);END LOOP;END $$;
